CREATE OR REPLACE FUNCTION public.tg_freight_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; prev numeric:=-1; op jsonb; BEGIN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF coalesce(NEW.regras->>'metodo','') NOT IN ('kg','tonelada','percentual','fixo','faixas') THEN RAISE EXCEPTION 'Método inválido'; END IF; IF coalesce((NEW.regras->>'tarifa')::numeric,0)<0 OR coalesce((NEW.regras->>'minimo')::numeric,0)<0 THEN RAISE EXCEPTION 'Valor inválido'; END IF; IF NEW.regras->>'metodo'='faixas' THEN IF jsonb_array_length(coalesce(NEW.regras->'faixas','[]'))=0 THEN RAISE EXCEPTION 'Cadastre as faixas'; END IF; FOR b IN SELECT value FROM jsonb_array_elements(NEW.regras->'faixas') ORDER BY (value->>'inicio')::numeric LOOP IF (b->>'inicio')::numeric<0 OR (b->>'fim')::numeric<=(b->>'inicio')::numeric OR (b->>'tarifa')::numeric<0 THEN RAISE EXCEPTION 'Faixa inválida'; END IF; IF prev=-1 AND (b->>'inicio')::numeric<>0 OR prev<>-1 AND (b->>'inicio')::numeric<>prev THEN RAISE EXCEPTION 'Faixas sobrepostas ou com intervalo não coberto'; END IF; IF b->>'unidade' NOT IN ('kg','tonelada','fixo') THEN RAISE EXCEPTION 'Unidade inválida'; END IF; prev:=(b->>'fim')::numeric; END LOOP; END IF; FOR op IN SELECT value FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) LOOP IF op->>'tipo' NOT IN ('percentual','fixo','minimo','icms','iss') OR op->>'base' NOT IN ('nf','frete','acumulado','contratual') OR (op->>'valor')::numeric<0 THEN RAISE EXCEPTION 'Operação inválida'; END IF; IF (op->>'tipo' IN ('icms','iss') OR op->>'por_dentro'='true') AND (op->>'valor')::numeric>=100 THEN RAISE EXCEPTION 'Percentual inválido'; END IF; IF op->>'substitui_base'='true' AND (op->>'tipo'<>'fixo' OR nullif(trim(op->>'cidade'),'') IS NULL OR nullif(trim(op->>'uf'),'') IS NULL) THEN RAISE EXCEPTION 'Substituição requer tarifa fixa, cidade e UF'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) x WHERE x->>'tipo'='icms' AND coalesce(x->>'habilitado','true')<>'false') AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) x WHERE x->>'tipo'='iss' AND coalesce(x->>'habilitado','true')<>'false') THEN RAISE EXCEPTION 'Configure ICMS ou ISS, não ambos'; END IF; PERFORM 1 FROM fornecedores WHERE id=NEW.fornecedor_id FOR UPDATE; SELECT coalesce(max(versao),0)+1 INTO NEW.versao FROM tabelas_frete WHERE fornecedor_id=NEW.fornecedor_id AND nome=NEW.nome; NEW.criado_por:=auth.uid(); RETURN NEW; END $$;